"""Actual same-origin navigation and responsive checks for the authorial supplement."""
def run_structural_equivalence_checks(page, check, screenshot, output, origin):
    base=origin.rstrip('/')+'/theology-wiki/'
    for entry in ['san-reader.html','index.html']:
        response=page.goto(base+entry,wait_until='domcontentloaded')
        check('Method supplement '+entry+' is delivered over HTTP',response.status==200)
        nav=page.get_by_role('navigation',name='Method and historical genealogy',exact=True)
        check('Method supplement '+entry+' navigation is visible',nav.is_visible())
        nav.get_by_role('link',name='New: Structural equivalence and the genealogy of ideas',exact=True).click()
        check('Method supplement '+entry+' links to full article',page.url.endswith('/structural-equivalence/index.html'))
        check('Method supplement '+entry+' retains full state-behavior section','genocide equivalence' in page.locator('article').inner_text())
    check('Method supplement needs no active scripts',page.locator('script').count()==0)
    check('Method supplement has eight section links',page.get_by_role('navigation',name='On this page',exact=True).locator('a').count()==8)
    screenshot(page,'structural-equivalence-desktop.png')
    page.get_by_role('navigation',name='On this page',exact=True).get_by_role('link',name='State behavior and genocide equivalence',exact=True).click()
    check('Method supplement section deep link works',page.url.endswith('#state-behavior-and-genocide-equivalence'))
    page.get_by_role('navigation',name='Research navigation',exact=True).get_by_role('link',name='Egypt and Iran',exact=True).click()
    check('Method supplement existing Egyptian Iranian study works',page.get_by_role('heading',level=1).inner_text().startswith("Ma'at"))
    page.go_back()
    page.get_by_role('navigation',name='Research navigation',exact=True).get_by_role('link',name='Moses, Jesus and Mammon',exact=True).click()
    check('Method supplement existing Moses Jesus study works',page.url.endswith('moses-jesus-mammon/index.html') and 'Moses' in page.locator('body').inner_text())
    page.goto(base+'structural-equivalence/index.html');page.set_viewport_size({'width':390,'height':844})
    check('Method supplement fits 390 pixel screen',page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'))
    screenshot(page,'structural-equivalence-mobile.png')
    page.get_by_role('navigation',name='On this page',exact=True).get_by_role('link',name='Signature clusters and narrative architecture',exact=True).click()
    check('Method supplement mobile section link works',page.url.endswith('#signature-clusters-and-narrative-architecture'))
    page.get_by_role('navigation',name='Research navigation',exact=True).get_by_role('link',name='Source Markdown',exact=True).click()
    check('Method supplement complete editable source is available',page.locator('body').inner_text().startswith('# Structural equivalence'))
    page.set_viewport_size({'width':1440,'height':1000})
